<template>
  <div>
    <header class="header">
      <button type="button" class="btn btn-back" @click="setState"></button>
      <h2 class="header-tit">{{ aName }}</h2>
      <button
        type="button"
        class="btn btn-star"
        v-bind:class="{ active: isFavo }"
        @click="btnFavorite"
      ></button>
    </header>
    <div class="content">
      <div class="map-top">
        <div class="price">
          <strong>{{ numberToKorean($store.state.AvailableAmount) }}</strong>
        </div>
        <div class="status-wrap">
          <Slider
            v-model="loan"
            :step="5"
            @change="slideChange"
            :tooltipPosition="'bottom'"
            :format="format"
          />
          <!-- <div class="status-bar">
            <div
              class="fill"
              :style="{ width: this.$store.state.LoanRate + '%' }"
            >
              <span class="percent">{{ this.$store.state.LoanRate }}%</span>
            </div>
          </div> -->
          <div class="tooltip">
            <button
              type="button"
              class="btn btn-info"
              @click="tooltip = true"
              v-bind:class="{ active: tooltip }"
            ></button>
            <div class="con">
              대출 비율을 조정하며 사용할 수 있어요
              <button
                type="button"
                class="btn btn-close"
                @click="tooltip = false"
              ></button>
            </div>
          </div>
        </div>
        <span
          class="check"
          @click="btnOption(1)"
          v-bind:class="{ grey: !option1 }"
        >
          <img src="../../../public/images/icon/check.svg" alt="" />
          거래 가능
        </span>
        <span
          class="check orange"
          @click="btnOption(2)"
          v-bind:class="{ grey: !option2 }"
        >
          <img src="../../../public/images/icon/check.svg" alt="" />
          대출 상향 시 거래 가능
        </span>
        <span class="check re" @click="backReturn">
          <img src="../../../public/images/icon/re.svg" alt="" />
          재설정
        </span>
      </div>
      <div class="box-line"></div>
      <ul class="detail-list">
        <template v-for="(item, idx) in itemList">
          <li
            v-if="item.AvailCount != 0 && option1"
            :key="'ii_0_' + item.Id + '_' + idx"
            class="detail-list--item"
          >
            <div class="left">
              <img src="../../../public/images/icon/cm.svg" alt="" />
              {{ Math.floor(item.Size) }}평
            </div>
            <div class="right">
              <strong>거래 가능합니다.</strong>
            </div>
          </li>
        </template>

        <template v-for="(item, idx) in itemList">
          <li
            v-if="item.AvailCount == 0 && item.LoanCount != 0 && option2"
            :key="'ii_1_' + item.Id + '_' + idx"
            class="detail-list--item orange"
          >
            <div class="left">
              <img src="../../../public/images/icon/cm.svg" alt="" />
              {{ Math.floor(item.Size) }}평
            </div>
            <div class="right">
              <strong>대출 비율 조정시 거래 가능합니다.</strong>
              상단의 대출 비율을 조정해보세요.
            </div>
          </li>
        </template>

        <template v-for="(item, idx) in itemList">
          <li
            v-if="item.AvailCount == 0 && item.LoanCount == 0"
            :key="'ii_2_' + item.Id + '_' + idx"
            class="detail-list--item grey"
          >
            <div class="left">
              <img src="../../../public/images/icon/cm.svg" alt="" />
              {{ Math.floor(item.Size) }}평
            </div>
            <div class="right"></div>
          </li>
        </template>
      </ul>
    </div>
    <button
      type="button"
      class="btn btn-full btn-gradient btn-fix"
      @click="sendConsult"
    >
      상담신청
    </button>
  </div>
</template>

<script>
import Slider from "@vueform/slider/dist/slider.vue2.js";
export default {
  name: "MapListDetail",
  props: {},
  components: { Slider },
  data() {
    return {
      tooltip: false,
      itemList: [],
      option1: true,
      option2: true,
      aName: "",
      aMinPrice: "",
      isFavo: false,
      loan: 0,
    };
  },
  mounted() {
    this.isFavo = this.$route.query.isFavorite;
    this.loan = this.$store.state.LoanRate;
    this.getItemList();
  },
  methods: {
    backReturn() {
      this.$store.state.reback = true;
      this.$router.push({
        name: "MyHomeMain",
      });
    },
    slideChange() {
      // this.getItems();
      this.getItemList();
      this.$store.state.LoanRate = this.loan;
    },
    sendConsult() {
      if (this.itemList.length > 0) {
        this.$apiPOST("/consult", { ApartmentId: this.itemList[0].Id }).then(
          ({ data }) => {
            if (data.code === 200) {
              alert("담당자 배정 후 상담 안내드리겠습니다.");
            }
          }
        );
      }
    },
    btnOption(type) {
      if (type === 1) {
        this.option1 = !this.option1;
      } else {
        this.option2 = !this.option2;
      }
    },
    getItemList() {
      this.$apiGET(
        "/map/apartment/detail?apartmentId=" +
          this.$route.query.apartmentId +
          "&loan=" +
          this.loan * 0.01
      ).then(({ data }) => {
        if (data.code === 200) {
          console.log(data.d);
          this.itemList = data.d;
          if (this.itemList.length > 0) {
            this.aName = this.itemList[0].Name;
            this.aMinPrice = this.numberToKorean(this.itemList[0].MinPrice);
          }
        }
      });
    },
    //라우터 코드로 이동
    clickList() {
      this.$router.push({
        name: "CreateReview",
        query: { name: "Query 프로그래밍 방식", age: 2 },
      });
    },
    clickParams() {
      this.$router.push({
        name: "CreateReview",
        params: { name: "Params 프로그래밍 방식", age: 2 },
      });
    },
    setState() {
      this.$router.go(-1);
    },
    numberToKorean(number) {
      var inputNumber = number < 0 ? false : number;
      var unitWords = ["", "만 ", "억 ", "조 ", "경 "];
      var splitUnit = 10000;
      var splitCount = unitWords.length;
      var resultArray = [];
      var resultString = "";

      for (var i = 0; i < splitCount; i++) {
        var unitResult =
          (inputNumber % Math.pow(splitUnit, i + 1)) / Math.pow(splitUnit, i);
        unitResult = Math.floor(unitResult);
        if (unitResult > 0) {
          resultArray[i] = unitResult;
        }
      }

      for (let i = 0; i < resultArray.length; i++) {
        if (!resultArray[i]) continue;
        resultString = String(resultArray[i]) + unitWords[i] + resultString;
      }

      return resultString;
    },
    btnFavorite() {
      this.$apiPOST("/favorite", {
        ApartmentId: this.$route.query.apartmentId,
        Type: !this.isFavo,
      }).then(({ data }) => {
        if (data.code === 200) {
          this.isFavo = !this.isFavo;
          for (let i = 0; i < this.$store.state._itemList.length; i++) {
            if (
              this.$store.state._itemList[i].Id == this.$route.query.apartmentId
            ) {
              this.$store.state._itemList[i].IsFavorite = this.isFavo;
              break;
            }
          }
        }
      });
    },
    format(value) {
      return `${value}%`;
    },
  },
};
</script>
