<template>
  <div class="wrap">
    <header class="header">
      <button
        type="button"
        class="btn btn-question"
        @click="qBtnState = true"
      ></button>
      <button type="button" class="btn btn-search text">
        {{ address }}
      </button>
      <!-- <button type="button" class="btn btn-menu"></button> -->
      <router-link :to="{ name: 'Setting' }" tag="button" class="btn btn-menu">
      </router-link>
    </header>
    <QuestionBtn :btnState="qBtnState" @setState="btnQuestion"></QuestionBtn>
    <div class="content">
      <div class="map-top">
        <div class="price">
          <strong>{{ numberToKorean($store.state.AvailableAmount) }}</strong>
        </div>
        <div class="status-wrap">
          <Slider
            v-model="loan"
            :step="5"
            @change="slideChange"
            :tooltipPosition="'bottom'"
            :format="format"
          />
          <!-- <div class="status-bar">
            <div
              class="fill"
              :style="{ width: this.$store.state.LoanRate + '%' }"
            >
              <span class="percent">{{ this.$store.state.LoanRate }}%</span>
            </div>
          </div> -->
          <div class="tooltip">
            <button
              type="button"
              class="btn btn-info"
              @click="tooltip = true"
              v-bind:class="{ active: tooltip }"
            ></button>
            <div class="con">
              대출 비율을 조정하며 사용할 수 있어요
              <button
                type="button"
                class="btn btn-close"
                @click="tooltip = false"
              ></button>
            </div>
          </div>
        </div>
        <span
          class="check"
          @click="btnOption(1)"
          v-bind:class="{ grey: !option1 }"
        >
          <img src="../../../public/images/icon/check.svg" alt="" />
          거래 가능
        </span>
        <span
          class="check orange"
          @click="btnOption(2)"
          v-bind:class="{ grey: !option2 }"
        >
          <img src="../../../public/images/icon/check.svg" alt="" />
          대출 상향 시 거래 가능
        </span>
        <span class="check re" @click="backReturn">
          <img src="../../../public/images/icon/re.svg" alt="" />
          재설정
        </span>
      </div>
      <div class="box-line"></div>
      <div v-if="itemList.length == 0" class="no-list">
        <img src="../../../public/images/no_list.svg" alt="" />
        거래 가능한 매물이 없습니다.
      </div>
      <ul v-else class="bookmark-list m-t--0">
        <template v-for="(item, idx) in itemList">
          <li
            v-if="item.AvailCount != 0 && option1"
            class="bookmark-list--item"
            @click="goDetail(item.Id, item.IsFavorite)"
            :key="'l_i_1_' + item.Id"
          >
            <div class="left">
              <strong class="tit">{{ item.Name }}</strong>
              <span class="price"
                >{{ item.PriceType }} {{ numberToKorean(item.MaxPrice) }}</span
              >
            </div>
            <div class="right">
              <button type="button" class="btn btn-house">
                {{ item.AvailCount }}
              </button>
              <button type="button" class="btn btn-house orange">
                {{ item.LoanCount }}
              </button>
              <button
                type="button"
                class="btn btn-star"
                v-bind:class="{ active: item.IsFavorite }"
                @click.stop
                @click="btnFavorite(idx)"
              ></button>
            </div>
          </li>
          <li
            v-else-if="item.AvailCount == 0 && option2"
            class="bookmark-list--item"
            @click="goDetail(item.Id, item.IsFavorite)"
            :key="'l_i_2_' + item.Id"
          >
            <div class="left">
              <strong class="tit">{{ item.Name }}</strong>
              <span class="price"
                >{{ item.PriceType }} {{ numberToKorean(item.MaxPrice) }}</span
              >
            </div>
            <div class="right">
              <button type="button" class="btn btn-house">
                {{ item.AvailCount }}
              </button>
              <button type="button" class="btn btn-house orange">
                {{ item.LoanCount }}
              </button>
              <button
                type="button"
                class="btn btn-star"
                v-bind:class="{ active: item.IsFavorite }"
                @click.stop
                @click="btnFavorite(idx)"
              ></button>
            </div>
          </li>
        </template>
      </ul>
    </div>
    <button type="button" class="btn btn-map" @click="setState">
      <img src="../../../public/images/icon/map.svg" alt="" />
      지도
    </button>
  </div>
</template>

<script>
import QuestionBtn from "../QuestionBtn.vue";
import Slider from "@vueform/slider/dist/slider.vue2.js";
export default {
  name: "MapList",
  props: {},
  components: { QuestionBtn, Slider },
  data() {
    return {
      tooltip: false,
      qBtnState: false,
      itemList: [],
      option1: true,
      option2: true,
      AvailableAmount: "",
      loan: 0,
      address: "",
    };
  },
  mounted() {
    this.itemList = this.$store.state._itemList;
    this.loan = this.$store.state.LoanRate;
    // this.getItems();
    this.address = this.$store.state._address.Name.replace(" ", " > ");
  },
  methods: {
    backReturn() {
      this.$store.state.reback = true;
      this.$router.push({
        name: "MyHomeMain",
      });
    },
    btnFavorite(idx) {
      this.$apiPOST("/favorite", {
        ApartmentId: this.itemList[idx].Id,
        Type: !this.itemList[idx].IsFavorite,
      }).then(({ data }) => {
        if (data.code === 200) {
          this.itemList[idx].IsFavorite = !this.itemList[idx].IsFavorite;
        }
      });
    },
    getItems() {
      this.itemList_ = this.itemList;
      this.markerState = false;
      const l = this.$store.state.l;
      const r = this.$store.state.r;
      const t = this.$store.state.t;
      const b = this.$store.state.b;
      this.$apiGET(
        "/map/apartment?l=" +
          l +
          "&r=" +
          r +
          "&t=" +
          t +
          "&b=" +
          b +
          "&loan=" +
          this.loan * 0.01
      ).then(({ data }) => {
        if (data.code === 200) {
          this.itemList = data.d;
        }
      });
    },
    slideChange() {
      this.getItems();
      this.$store.state.LoanRate = this.loan;
    },
    btnOption(type) {
      if (type === 1) {
        this.option1 = !this.option1;
      } else {
        this.option2 = !this.option2;
      }
    },
    btnQuestion(st) {
      this.qBtnState = st;
    },
    //라우터 코드로 이동
    clickList() {
      this.$router.push({
        name: "CreateReview",
        query: { name: "Query 프로그래밍 방식", age: 2 },
      });
    },
    goDetail(id, isFavorite) {
      this.$router.push({
        name: "MapListDetail",
        query: {
          apartmentId: id,
          loan: this.$store.state.LoanRate * 0.01,
          isFavorite: isFavorite,
        },
      });
    },
    setState() {
      // console.log(this.$router.getRoutes());
      this.$router.go(-1);

      // this.$emit("setState", false);
    },
    numberToKorean(number) {
      var inputNumber = number < 0 ? false : number;
      var unitWords = ["", "만 ", "억 ", "조 ", "경 "];
      var splitUnit = 10000;
      var splitCount = unitWords.length;
      var resultArray = [];
      var resultString = "";

      for (var i = 0; i < splitCount; i++) {
        var unitResult =
          (inputNumber % Math.pow(splitUnit, i + 1)) / Math.pow(splitUnit, i);
        unitResult = Math.floor(unitResult);
        if (unitResult > 0) {
          resultArray[i] = unitResult;
        }
      }

      for (let i = 0; i < resultArray.length; i++) {
        if (!resultArray[i]) continue;
        resultString = String(resultArray[i]) + unitWords[i] + resultString;
      }

      return resultString;
    },
    format(value) {
      return `${value}%`;
    },
  },
};
</script>
