<template>
  <div>
    <div class="wrap" v-show="!mBtnState">
      <header class="header">
        <button
          type="button"
          class="btn btn-question"
          @click="qBtnState = true"
        ></button>
        <button type="button" class="btn btn-search" @click="mBtnState = true">
          <img src="../../../public/images/icon/search.svg" alt="" />
          찾고 있는 지역이 있으신가요?
        </button>

        <router-link
          :to="{ name: 'Setting' }"
          tag="button"
          class="btn btn-menu"
        >
        </router-link>
      </header>
      <QuestionBtn :btnState="qBtnState" @setState="btnQuestion"></QuestionBtn>
      <div class="content">
        <div class="map-top">
          <div class="price">
            <strong>{{ numberToKorean(AvailableAmount) }}</strong>
          </div>
          <div class="status-wrap">
            <Slider
              v-model="loan"
              :step="5"
              @change="slideChange"
              :tooltipPosition="'bottom'"
              :format="format"
            />
            <!-- <div class="status-bar">
              <button
                type="button"
                class="btn"
                :style="{ left: 'calc(' + loan + '% - 8px)' }"
              ></button>
              <div class="fill" :style="{ width: loan + '%' }">
                <span class="percent">{{ loan }}%</span>
              </div>
            </div> -->
            <div class="tooltip">
              <button
                type="button"
                class="btn btn-info"
                @click="tooltip = true"
                v-bind:class="{ active: tooltip }"
              ></button>
              <div class="con">
                대출 비율을 조정하며 사용할 수 있어요
                <button
                  type="button"
                  class="btn btn-close"
                  @click="tooltip = false"
                ></button>
              </div>
            </div>
          </div>
          <span
            class="check"
            @click="btnOption(1)"
            v-bind:class="{ grey: !option1 }"
          >
            <img src="../../../public/images/icon/check.svg" alt="" />
            거래 가능
          </span>
          <span
            class="check orange"
            @click="btnOption(2)"
            v-bind:class="{ grey: !option2 }"
          >
            <img src="../../../public/images/icon/check.svg" alt="" />
            대출 상향 시 거래 가능
          </span>
          <span class="check re" @click="backReturn">
            <img src="../../../public/images/icon/re.svg" alt="" />
            재설정
          </span>
          <!-- <router-link
            :to="{
              name: 'MyHomeMain',
            }"
            tag="span"
            class="check re"
          >
            <img src="../../../public/images/icon/re.svg" alt="" />
            재설정
          </router-link> -->
        </div>
        <div class="map-wrap" ref="mapWrap">
          <naver-maps
            v-if="mapState"
            :height="height"
            :width="width"
            :mapOptions="mapOptions"
            :initLayers="initLayers"
            @zoom_changed="zoomChanged"
            @load="onLoad"
            @dragend="dragend"
          >
            <template v-if="zoomLevel >= maxMarker">
              <template v-if="markerState">
                <naver-marker
                  v-for="item in itemList"
                  v-bind:key="'m_' + item.Id"
                  :lat="item.Lat"
                  :lng="item.Lng"
                  @click="onMarkerClicked"
                  @load="onMarkerLoaded"
                >
                  <div
                    v-if="item.AvailCount != 0 && option1"
                    @click="goDetail(item.Id)"
                    class="count sm"
                    style="left: 20px; top: 20px"
                    v-bind:class="{ lg: zoomLevel >= 18 }"
                  >
                    {{ item.AvailCount }}
                  </div>
                  <div
                    v-else-if="item.AvailCount == 0 && option2"
                    @click="goDetail(item.Id)"
                    class="count orange sm"
                    style="left: 20px; top: 20px"
                    v-bind:class="{ lg: zoomLevel >= 18 }"
                  >
                    {{ item.LoanCount }}
                  </div>
                  <div v-else></div>
                  <!-- <div class="count lg" style="left: 100px; top: 100px">10</div> -->
                </naver-marker>
              </template>
              <template v-else>
                <naver-marker
                  v-for="item in itemList_"
                  v-bind:key="'m_T' + item.Id"
                  :lat="item.Lat"
                  :lng="item.Lng"
                  @click="onMarkerClicked"
                  @load="onMarkerLoaded"
                >
                  <div
                    v-if="item.AvailCount != 0 && option1"
                    class="count sm"
                    style="left: 20px; top: 20px"
                    v-bind:class="{ lg: zoomLevel >= 18 }"
                  >
                    {{ item.AvailCount }}
                  </div>
                  <div
                    v-else-if="item.AvailCount == 0 && option2"
                    class="count orange sm"
                    style="left: 20px; top: 20px"
                    v-bind:class="{ lg: zoomLevel >= 18 }"
                  >
                    {{ item.LoanCount }}
                  </div>
                  <div v-else></div>
                  <!-- <div class="count lg" style="left: 100px; top: 100px">10</div> -->
                </naver-marker>
              </template>
            </template>
          </naver-maps>
        </div>
      </div>
      <!-- <router-link
        :to="{
          name: 'MapList',
        }"
        tag="button"
        class="btn btn-list"
      >
      </router-link> -->
      <button class="btn btn-list" @click="goMapList">
        <img src="../../../public/images/icon/home_menu.svg" alt="" />
        목록
      </button>
      <div class="con-bottom">
        <div class="status-top">
          <p
            class="
              font-size--12
              font-color--l-grey
              text-height--3
              font-weight--3
            "
          >
            <strong class="font-size--14 font-color--black">{{
              address.Name
            }}</strong
            ><br />
            {{ address.ReviewCount }}개의 내집 장만 후기가 있습니다.
          </p>
          <!-- <button type="button" class="btn btn-md btn-gradient btn-up">
            후기 보기
            <img src="../../../public/images/icon/arrow_up.svg" alt="" />
          </button> -->
          <button class="btn btn-md btn-gradient btn-up" @click="goReview">
            후기 보기
            <img src="../../../public/images/icon/arrow_up.svg" alt="" />
          </button>
        </div>
      </div>
    </div>
    <MapSearch
      v-show="mBtnState"
      @setState="btnMapSearch"
      @searchReturn="searchReturn"
    ></MapSearch>
  </div>
</template>

<script>
import QuestionBtn from "../QuestionBtn.vue";
import MapSearch from "./MapSearch.vue";
// import MapList from "./MapList.vue";
import Slider from "@vueform/slider/dist/slider.vue2.js";

export default {
  name: "MapMain",
  props: {},
  //   MapSearch, MapList
  components: { QuestionBtn, MapSearch, Slider },
  data() {
    return {
      tooltip: false,
      maxMarker: 16,
      address: "",
      loan: 0,
      qBtnState: false,
      mBtnState: false,
      mapState: false,
      markerState: false,
      option1: true,
      option2: true,
      AvailableAmount: "",
      itemList: [],
      itemList_: [],
      zoomLevel: 16,
      width: 0,
      height: 0,
      // width: window.innerWidth,
      // height: window.innerHeight - 100,
      info: false,
      marker: null,
      count: 1,
      map: null,
      isCTT: false,
      mapOptions: {
        minZoom: 8,
        maxZoom: 19,
        lat: 37,
        lng: 127,
        zoom: 16,
        scaleControl: false,
        // scaleControlOptions: {
        //   position: "TOP_CENTER",
        // },
        mapDataControl: false,
        // mapDataControlOptions: {
        //   position: "TOP_CENTER",
        // },
        mapTypeControl: false,
        zoomControl: false,
        // zoomControlOptions: { position: "TOPRIGHT" },
        logoControl: true,
        logoControlOptions: { position: "TOP_RIGHT" },
      },
      initLayers: [
        "BACKGROUND",
        "BACKGROUND_DETAIL",
        "POI_KOREAN",
        "TRANSIT",
        "ENGLISH",
        "CHINESE",
        "JAPANESE",
      ],
    };
  },
  created() {
    this.getUserData();
  },
  updated() {
    // this.removeLogo();
  },
  mounted() {
    this.$nextTick(() => {
      this.height = this.$refs.mapWrap.offsetHeight;
      this.width = this.$refs.mapWrap.offsetWidth;
      let st = false;
      if (this.$store.state.lat != null && this.$store.state.lng != null) {
        st = true;
      }
      this.getPoint(st);
    });
  },
  methods: {
    removeLogo() {
      var naverMap = document.getElementById("vue-naver-maps");
      var naverMapA = null;
      if (naverMap.getElementsByTagName("a").length > 0) {
        naverMapA = naverMap.getElementsByTagName("a")[0];
        naverMapA.parentElement.parentElement.remove();
      }
    },
    backReturn() {
      this.$store.state.reback = true;
      this.$router.push({
        name: "MyHomeMain",
      });
    },
    slideChange() {
      this.getItems();
      this.$store.state.LoanRate = this.loan;
    },
    goDetail(id) {
      this.saveInfo();
      this.$router.push({
        name: "MapListDetail",
        query: { apartmentId: id, loan: this.loan * 0.01 },
      });
    },
    getAddress(lng, lat) {
      this.$apiGET("/map/addr?coords=" + lng + "," + lat).then(({ data }) => {
        if (data.code === 200) {
          this.address = data.d;
          this.$store.state._address = this.address;
        }
      });
    },
    getUserData() {
      if (this.$store.state.lat != null) {
        this.mapOptions.lat = this.$store.state.lat;
        this.mapOptions.lng = this.$store.state.lng;
        this.AvailableAmount = this.$store.state.AvailableAmount;
        this.loan = this.$store.state.LoanRate;
      } else {
        this.$apiGET("/map/info").then(({ data }) => {
          if (data.code === 200) {
            this.$store.state.AvailableAmount = data.d.AvailableAmount;
            this.$store.state.LoanRate = data.d.LoanRate;
            this.$store.state.lat = data.d.dvsn.Lat;
            this.$store.state.lng = data.d.dvsn.Lng;

            this.mapOptions.lat = this.$store.state.lat;
            this.mapOptions.lng = this.$store.state.lng;
            this.AvailableAmount = this.$store.state.AvailableAmount;
            this.loan = this.$store.state.LoanRate;
          }
        });
      }
    },
    getPoint(st) {
      if (st == true) {
        this.mapOptions.lat = this.$store.state.lat;
        this.mapOptions.lng = this.$store.state.lng;
        this.mapState = true;
        // this.getAddress(this.mapOptions.lng, this.mapOptions.lat);
      } else {
        this.$apiGET("/map/region").then(({ data }) => {
          // console.log(data.d.city);
          // console.log(data.d.dvsn);
          this.mapOptions.lat = data.d.dvsn.Lat;
          this.mapOptions.lng = data.d.dvsn.Lng;
          this.mapState = true;
          // this.getAddress(this.mapOptions.lng, this.mapOptions.lat);
        });
      }
    },
    saveInfo() {
      this.$store.state._itemList = this.itemList;
      this.$store.state.lat = this.map.map.center._lat;
      this.$store.state.lng = this.map.map.center._lng;
      this.$store.state._zoomLevel = this.zoomLevel;
      this.savePostion();
    },
    savePostion() {
      if (this.zoomLevel >= this.maxMarker) {
        const po = this.map.getBounds();
        this.$store.state.l = po._sw._lng;
        this.$store.state.r = po._ne._lng;
        this.$store.state.t = po._ne._lat;
        this.$store.state.b = po._sw._lat;
      }
    },
    numberToKorean(number) {
      var inputNumber = number < 0 ? false : number;
      var unitWords = ["", "만 ", "억 ", "조 ", "경 "];
      var splitUnit = 10000;
      var splitCount = unitWords.length;
      var resultArray = [];
      var resultString = "";

      for (var i = 0; i < splitCount; i++) {
        var unitResult =
          (inputNumber % Math.pow(splitUnit, i + 1)) / Math.pow(splitUnit, i);
        unitResult = Math.floor(unitResult);
        if (unitResult > 0) {
          resultArray[i] = unitResult;
        }
      }

      for (let i = 0; i < resultArray.length; i++) {
        if (!resultArray[i]) continue;
        resultString = String(resultArray[i]) + unitWords[i] + resultString;
      }

      return resultString;
    },
    goReview() {
      this.saveInfo();
      this.$router.push({
        name: "MapReview",
      });
    },
    goMapList() {
      this.saveInfo();
      this.$router.push({
        name: "MapList",
      });
    },
    searchReturn(re) {
      this.map.setCenter(re.Lat, re.Lng);
      this.zoomLevel = 13;
      this.map.setZoom(this.zoomLevel);
      this.getItems();

      // console.log(this.map.setCenter(re.Lat, re.Lng));
    },
    btnOption(type) {
      if (type === 1) {
        this.option1 = !this.option1;
      } else {
        this.option2 = !this.option2;
      }
    },

    getItems() {
      if (this.zoomLevel >= this.maxMarker) {
        this.itemList_ = this.itemList;
        this.markerState = false;
        const po = this.map.getBounds();
        const l = po._sw._lng;
        const r = po._ne._lng;
        const t = po._ne._lat;
        const b = po._sw._lat;
        this.$apiGET(
          "/map/apartment?l=" +
            l +
            "&r=" +
            r +
            "&t=" +
            t +
            "&b=" +
            b +
            "&loan=" +
            this.loan * 0.01
        ).then(({ data }) => {
          if (data.code === 200) {
            // if (this.itemList.length > 0) {
            //   this.itemList = data.d.filter((x) => !this.itemList.includes(x));
            // } else {
            //   this.itemList = data.d;
            // }

            this.itemList = data.d;
            this.markerState = true;
            this.savePostion();
          }
        });
      }
      this.getAddress(this.map.map.center._lng, this.map.map.center._lat);
    },
    dragend() {
      this.getItems();
      this.saveInfo();
    },
    zoomChanged(zoom) {
      this.zoomLevel = zoom;
      this.getItems();
      this.saveInfo();
      // this.itemList = [];
      // this.itemList = [{ id: 1, lat: 37.565829, lng: 127.054617 }];
    },
    zoomController() {
      this.map.setZoom(this.zoomLevel);
    },
    onLoad(vue) {
      this.map = vue;

      this.map.setOptions({
        logoControlOptions: {
          position: 3,
        },
      });

      console.log(window.naver.maps.Position);
      this.getItems();
    },
    onWindowLoad() {},
    onMarkerClicked() {
      this.info = !this.info;
    },
    onMarkerLoaded() {
      // this.marker = vue.marker;
      // console.log(this.marker);
    },
    btnQuestion(st) {
      this.qBtnState = st;
    },
    btnMapSearch(st) {
      this.mBtnState = st;
    },
    //라우터 코드로 이동
    clickList() {
      this.$router.push({
        name: "CreateReview",
        query: { name: "Query 프로그래밍 방식", age: 2 },
      });
    },
    clickParams() {
      this.$router.push({
        name: "CreateReview",
        params: { name: "Params 프로그래밍 방식", age: 2 },
      });
    },
    setState() {
      this.$emit("setState", false);
    },
    format(value) {
      return `${value}%`;
    },
  },
};
</script>
<style src="@vueform/slider/themes/default.css"></style>
