<template>
  <div class="wrap splash">
    <p class="greeting">
      내 집 장만!<br />
      하우머치 홈즈로 시작하세요!
    </p>
    <router-link
      :to="{ name: 'MyHomeMain' }"
      tag="button"
      class="btn btn-myhome"
    >
      <img src="../../public/images/icon/plus.svg" alt="" />마이홈
    </router-link>
    <br />
    <router-link
      :to="{ name: 'ReviewMain' }"
      tag="button"
      class="btn btn-review"
    >
      내 집 마련 후기 보기
    </router-link>
  </div>
</template>

<script>
export default {
  name: "HowMain",
  props: {
    msg: String,
  },
  components: {},
  data() {
    return {};
  },
  mounted() {
    this.init();
    this.$nextTick(() => {
      if (this.$getAppCheck() == "android") {
        window.Android.SetWebViewVisible();
      }
    });

    if (this.$route.query.id != undefined) {
      this.$store.state.rId = this.$route.query.id;

      this.$router.push({
        name: "ReviewMain",
      });
    }
  },
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.$store.commit("init");
    },
    testFunc(re) {
      alert(re);
    },
    //라우터 코드로 이동
    clickList() {
      this.$router.push({
        name: "CreateReview",
        query: { name: "Query 프로그래밍 방식", age: 2 },
      });
    },
    clickParams() {
      this.$router.push({
        name: "CreateReview",
        params: { name: "Params 프로그래밍 방식", age: 2 },
      });
    },
  },
};
</script>
